SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0550000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 55, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "55", "printedPageNumber": 55, "pdfPageNumber": 438, "sequenceIndex": 45, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0550100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith IV", "sourceIdentifier": "IV", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0550000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part II (a)—Rewards of Jamaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 55"}, {"id": "f0550100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "carding the Sunnah of the Prophet (Sallallaho alaihe wasallam) and no sooner you desert his Sunnah than you go astray. When a person performs wudhu correctly and then leaves for the musjid, at each step that he takes, he gets one blessing and has one sin wiped out. During the lifetime of the Prophet (Sallallaho alaihe wasallam) no one would miss Jamaat except an open munaafiq or a real invalid. Even the munaafiq dared not miss the Jamaat and a sick person who could be taken to the musjid with the help of two men would be helped to join Jamaat.\"\n\nThis shows the extreme vigilance of the Sahabah over their salaat with Jamaat. Even a sick person was brought to the musjid somehow or other, even though it needed two men to help him. This concern was quite natural when they found the Prophet (Sallallaho alaihe wasallam) himself so very particular about it. It is said that when the Prophet (Sallallaho alaihe wasallam) was on his deathbed, and he would frequently faint; he succeeded in making wudhu after several attempts and, though he could hardly stand, went to the musjid with the help of Hadhrat Abbas (Radhiyallaho anho) and another companion. Hadhrat Abu Bakr (Radhiyallaho anho) led the salaat at his instance, and he himself joined the Jamaat.\n\nHadhrat Abu Darda (Radhiyallaho anho) narrates that the Prophet (Sallallaho alaihe wasallam) once said to him, \"Worship your Lord as if you see Him before you, count yourself among the dead, beware of the curse of the wronged ones and, even if you could crawl to the musjid, do not miss Ishaa and Fajr with Jamaat.\"\n\nIt is said in another hadith, \"Ishaa and Fajr are very heavy on those who are munaafiq. If they knew the reward of the Jamaat, they would go to the musjid and join the Jamaat even if they had to crawl.\"\n\n", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 55"}, {"id": "f0550200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Anas bin Maalik (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 55"}, {"id": "f0550300-0000-4000-8000-000000000001", "structuralNodeId": "b0550100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith IV", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 55"}, {"id": "f0550400-0000-4000-8000-000000000001", "structuralNodeId": "b0550100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن أنس بن مالك رضي الله عنه قال قال رسول الله ﷺ من صلى لله أربعين يوماً في جماعة يدرك التكبيرة الأولى كتب له براءتان براءة من النار وبراءة من النفاق رواه الترمذي", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 55"}]}'::jsonb);